struct R{uint64_t s,i;__device__ uint32_t n(){uint64_t o=s;s=o*MULT+i;uint32_t x=uint32_t(((o>>18)^o)>>27),r=uint32_t(o>>59);return(x>>r)|(x<<((-r)&31));}__device__ void init(uint64_t v){s=0;i=(0x484AULL<<1)|1;n();s+=v;n();}__device__ int b(int v){return int(n()%uint32_t(v));}__device__ double u(){return double(n())/4294967296.0;}};
