__global__ void run(const unsigned char*t,const uint16_t*l,int count,const double*q,uint64_t seed,int it,double t0,double t1,double*out,unsigned char*ob){int z=blockIdx.x*blockDim.x+threadIdx.x;if(z>=count)return;const unsigned char*x=t+size_t(z)*STRIDE;int n=l[z];R r;r.init(ds(seed,z,0));unsigned char b[S],bestb[S];for(int i=0;i<S;++i)b[i]=i;for(int i=S-1;i>0;--i){int j=r.b(i+1);unsigned char v=b[i];b[i]=b[j];b[j]=v;}double cur=0;for(int p=3;p<n;++p)cur+=q[k(b[x[p-3]],b[x[p-2]],b[x[p-1]],b[x[p]])];double best=cur;for(int i=0;i<S;++i)bestb[i]=b[i];double cool=it?pow(t1/t0,1.0/double(it)):1,temp=t0;for(int step=0;step<it;++step){int a=r.b(S),c=r.b(S);if(a!=c){double d=0;for(int p=3;p<n;++p){unsigned char s0=x[p-3],s1=x[p-2],s2=x[p-1],s3=x[p];if(s0==a||s0==c||s1==a||s1==c||s2==a||s2==c||s3==a||s3==c){unsigned char a0=b[s0],a1=b[s1],a2=b[s2],a3=b[s3];unsigned char c0=s0==a?b[c]:(s0==c?b[a]:a0),c1=s1==a?b[c]:(s1==c?b[a]:a1),c2=s2==a?b[c]:(s2==c?b[a]:a2),c3=s3==a?b[c]:(s3==c?b[a]:a3);d+=q[k(c0,c1,c2,c3)]-q[k(a0,a1,a2,a3)];}}if(d>=0||r.u()<exp(d/temp)){unsigned char v=b[a];b[a]=b[c];b[c]=v;cur+=d;if(cur>best){best=cur;for(int i=0;i<S;++i)bestb[i]=b[i];}}}temp*=cool;}out[z]=best/double(n-3);for(int i=0;i<S;++i)ob[size_t(z)*S+i]=bestb[i];}
