int main(){char m[8];if(!rd(m,size_t(8))||std::memcmp(m,"P484QF1\0",8))return 3;uint32_t h[2];uint64_t seed;double temp[2];if(!rd(h,size_t(2))||!rd(&seed,size_t(1))||!rd(temp,size_t(2)))return 3;size_t count=h[0];int it=h[1];if(!count||count>(1u<<20)||temp[0]<=0||temp[1]<=0)return 4;std::vector<uint16_t>len(count);std::vector<unsigned char>tok(count*STRIDE),boards(count*S);std::vector<double>quad(Q),scores(count);if(!rd(len.data(),count)||!rd(tok.data(),count*STRIDE)||!rd(quad.data(),Q))return 3;for(auto n:len)if(n<4||n>STRIDE)return 4;uint16_t*dl;unsigned char*dt,*db;double*dq,*doo;CK(cudaMalloc(&dl,count*sizeof(uint16_t)));CK(cudaMalloc(&dt,count*STRIDE));CK(cudaMalloc(&db,count*S));CK(cudaMalloc(&dq,Q*sizeof(double)));CK(cudaMalloc(&doo,count*sizeof(double)));CK(cudaMemcpy(dl,len.data(),count*sizeof(uint16_t),cudaMemcpyHostToDevice));CK(cudaMemcpy(dt,tok.data(),count*STRIDE,cudaMemcpyHostToDevice));CK(cudaMemcpy(dq,quad.data(),Q*sizeof(double),cudaMemcpyHostToDevice));run<<<(count+127)/128,128>>>(dt,dl,int(count),dq,seed,it,temp[0],temp[1],doo,db);CK(cudaGetLastError());CK(cudaDeviceSynchronize());CK(cudaMemcpy(scores.data(),doo,count*sizeof(double),cudaMemcpyDeviceToHost));CK(cudaMemcpy(boards.data(),db,count*S,cudaMemcpyDeviceToHost));if(std::fwrite(scores.data(),sizeof(double),count,stdout)!=count||std::fwrite(boards.data(),1,count*S,stdout)!=count*S)return 5;return 0;}
